<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Outstanding Fee Balances</h1><p>Unpaid and partially paid invoices</p></div></header><section class="module-card"><div class="module-card__body"><table class="data-table"><thead><tr><th>Student</th><th>Registration</th><th>Class</th><th>Month</th><th>Status</th><th>Outstanding</th></tr></thead><tbody><?php if(!$outstanding):?><tr><td colspan="6">No outstanding balances.</td></tr><?php else:foreach($outstanding as$row):?><tr><td><?= e($row['student_name']) ?></td><td><?= e($row['registration_no']) ?></td><td><?= e($row['class_name']) ?></td><td><?= e($row['fee_month']) ?></td><td><?= e($row['status']) ?></td><td><?= number_format((float)$row['remaining_amount'],2) ?></td></tr><?php endforeach;endif ?></tbody></table></div></section></div></div></main>
